        queryClient.invalidateQueries({ queryKey: tagsKey(sheet) }),
      ]);
    },
    onError: async (e, input) => {
      if (e instanceof HttpError && e.status === 409) {
        // Someone else saved this person since the editor loaded it: show what is stored now.
        await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
        const current = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((p) => p.id === editing);
        if (current) {
          version.current = current.version;
          setForm(fill(current));
        }
        setError('Someone else saved this person meanwhile; the form now shows their values.');
        return;
      }
      const key = input.name.trim().toLowerCase();
      const taken = people.data?.some((p) => p.id !== editing && p.name.trim().toLowerCase() === key);
      // A refused edit changes nothing: the editor closes, back to adding, with the refusal showing.
      if (editing !== undefined) {
        setEditing(undefined);
        setForm(EMPTY);
      }
      const contact = input.contact.trim().toLowerCase();
      const contactTaken = contact !== '' && people.data?.some((p) => p.id !== editing && p.contact === contact);
      setError(
        taken
          ? 'That name is already in use.'
          : contactTaken
            ? 'That contact is already in use.'
            : 'That person could not be saved.',
      );
    },
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('Type a name.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <form onSubmit={submit} data-testid="person-form">
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={form.name}
        onChange={(e) => change({ name: e.target.value })}
      />
      <select
        data-testid="person-form-grade"
        value={form.grade}
        onChange={(e) => change({ grade: e.target.value })}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>
      <input
        data-testid="person-form-grade-from"
        type="date"
        title="Grade from (blank: the sheet's today)"
        value={form.gradeFrom}
        onChange={(e) => change({ gradeFrom: e.target.value })}
      />
      <input
        data-testid="person-form-terms"
        placeholder="Terms (days)"
        title="The person's own terms in days (blank: none)"
        value={form.terms}
        onChange={(e) => change({ terms: e.target.value })}
      />
      <input
        data-testid="person-form-contact"
        placeholder="Contact"
        title="The person's contact (blank: none)"
        value={form.contact}
        onChange={(e) => change({ contact: e.target.value })}
      />
      <input
        data-testid="person-form-tags"
        placeholder="Tags"
        title="The person's tags, comma separated (blank: none)"
        value={form.tags}
        onChange={(e) => change({ tags: e.target.value })}
      />
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing === undefined ? 'Add person' : 'Save person'}
      </button>
      {editing !== undefined && (
        <button type="button" data-testid="person-form-cancel" onClick={close}>
          Cancel
        </button>
      )}
      {error && <span data-testid="person-form-error">{error}</span>}
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade recorded for a person, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: string; from: string | null };

/** The grade in force on the date (yyyy-MM-dd): the one recorded with the latest from-date on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** A hold on a person, from its from-date to its to-date, both inclusive (yyyy-MM-dd; null: open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether a hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to);

/**
 * The holds that apply to a person's live totals on the sheet's `today`: their own, and — from the day their
 * retirement date is reached — one covering every date, so their open and pending claims leave the totals as a
 * hold's would (settled ones, and ones a statement binds, still count).
 */
export const liveHolds = (p: { holds: Hold[]; retiredFrom: string | null }, today: string): Hold[] =>
  p.retiredFrom !== null && today !== '' && today >= p.retiredFrom ? [...p.holds, { from: null, to: null }] : p.holds;

/**
 * A person on the sheet as the store holds them; `grade` is the one in force on the sheet's today and
 * `grades` every grade recorded for them, each from its from-date; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they have any hold, `holds` each hold, oldest first: their open claims dated within one, and not bound by a
 * statement, count in no live total. `terms` is the person's own terms in days, null when they have none;
 * `contact` their contact (trimmed, lower-cased), null when they have none. `clashing` is whether another sheet of
 * the sheet's tree (its ancestors and descendants) uses their name or any of their aliases as a name or alias.
 * `origin` is the sheet they were transferred from, null when they were not transferred here. `pastRetirements` are
 * the retirements they were unretired from, oldest first: a claim dated after one's from and before its to is refused.
 * `tags` are their tags, sorted (none: empty).
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
  clashing: boolean;
  origin: string | null;
  pastRetirements: { from: string; to: string }[];
  tags: string[];
};

/**
 * The fields the person form submits; a blank `gradeFrom` is the sheet's today, blank `terms` none of their own,
 * blank `contact` none, `tags` comma separated (blank: none).
 */
export type PersonInput = { name: string; grade: string; gradeFrom: string; terms: string; contact: string; tags: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in their order in the list (new people go to the end; they can be moved up and down). */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);

/** Whether retired people are listed; off until the toggle is turned on, and kept when a sheet is loaded. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** The keys the people list can be sorted on. */
export const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
export type SortKey = (typeof SORT_KEYS)[number];

/** How this screen sorts the people list; added (their order in the list) until another key is chosen. */
export const usePeopleSort = () =>
  useSearchParam<SortKey>('sort', (raw) => (SORT_KEYS as readonly unknown[]).includes(raw) ? (raw as SortKey) : 'added');

/** A name as names are compared: trimmed and lower-cased. */
export const nameKey = (name: string) => name.trim().toLowerCase();
import { useSyncExternalStore } from 'react';
import { useCurrentSheet } from '../session/session';

// One error per person row, shared by every action on the row (a statement, a retirement, ...): the
// row shows it once, in its last cell, and the next action on the row clears it. An action whose error
// shows in its own cell (naming a patron) keeps it under its own kind; setting any error clears them all.
const errors = new Map<string, string>();
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The person row's error of this kind ('' when none) and the setter every action on the row uses. */
export function usePersonError(personId: number, kind = ''): [string, (message: string) => void] {
  const [sheet] = useCurrentSheet();
  const row = `${sheet}:${personId}`;
  const key = kind ? `${row}:${kind}` : row;
  const error = useSyncExternalStore(subscribe, () => errors.get(key) ?? '');
  const setError = (message: string) => setPersonError(sheet, personId, message, kind);
  return [error, setError];
}

/** Set (or, with '', clear) a person row's error from outside the row, as a bulk action does. */
export function setPersonError(sheet: string, personId: number, message: string, kind = '') {
  const row = `${sheet}:${personId}`;
  const key = kind ? `${row}:${kind}` : row;
  for (const k of [...errors.keys()]) {
    if (k === row || k.startsWith(`${row}:`)) errors.delete(k);
  }
  if (message) errors.set(key, message);
  listeners.forEach((l) => l());
}

/** The person row's error, when there is one. */
export function PersonError({ personId }: { personId: number }) {
  const [error] = usePersonError(personId);
  return error ? <span data-testid="person-error">{error}</span> : null;
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { sheetKey, useCurrentSheet, useCurrentUser } from '../session/session';
import { GRADES, usePeople } from './people';
import type { Person } from './people';
import { setPersonError } from './personError';
import { useSelectedPeople } from './selection';

// Gives every ticked person a grade from a date (blank: the sheet's today), one after another in list
// order. Each goes through the person's own edit, exactly as the person form saves it (keeping their
// name, terms and contact, from the version listed), so it is audited and rolled up the same way. One the server
// refuses is left as it is and shows the refusal on its row; the count is of those changed.
export function BulkGrade() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const [selected, , clear] = useSelectedPeople();
  const [grade, setGrade] = useState<string>(GRADES[0]);
  const [from, setFrom] = useState('');
  const [graded, setGraded] = useState<number | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setGraded(undefined);
    setBusy(true);
    const ordered = people.filter((p) => selected.has(p.id));
    let changed = 0;
    for (const p of ordered) setPersonError(sheet, p.id, '');
    try {
      for (const p of ordered) {
        try {
          await putJson<Person>(
            `/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}?user=${encodeURIComponent(user)}`,
            { name: p.name, grade, gradeFrom: from, terms: p.terms == null ? '' : String(p.terms),
              contact: p.contact ?? '', tags: p.tags.join(','), version: p.version },
          );
          changed++;
        } catch {
          setPersonError(sheet, p.id, 'That person could not be given the grade.');
        }
      }
      clear();
      await queryClient.invalidateQueries({ queryKey: sheetKey(sheet) });
    } finally {
      setBusy(false);
      setGraded(changed);
    }
  };

  return (
    <p>
      <select data-testid="bulk-grade" value={grade} onChange={(e) => setGrade(e.target.value)}>
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="bulk-grade-from"
        type="date"
        title="Grade from (blank: the sheet's today)"
        value={from}
        onChange={(e) => setFrom(e.target.value)}
      />{' '}
      <button type="button" data-testid="bulk-grade-apply" disabled={busy} onClick={() => once(run)}>
        Grade selected people
      </button>
      {graded !== undefined && (
        <>
          {' '}
          Changed <span data-testid="bulk-graded">{graded}</span>
        </>
      )}
    </p>
  );
}
