import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { PersonError } from './personError';
import { useClaims } from '../claims/claims';
import { NA, personDue, useRates } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import { liveHolds, nameKey, useEditingPerson, usePeople, usePeopleSort, useShowRetired } from './people';
import type { Person, SortKey } from './people';

/** Orders a and b by key: negative, zero or positive. */
const compare = (a: string | number, b: string | number) => (a < b ? -1 : a > b ? 1 : 0);

// Every person on the sheet, in their order in the list (their positions) or sorted as this screen chose, each with their name and grade and
// the columns features add (slots/defs/personColumns.ts). Retired people are left out unless the
// show-retired toggle is on.
export function PeopleList() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople();
  const [showRetired] = useShowRetired();
  const [sort] = usePeopleSort();
  const sortKey = useSortKey(sort);

  if (!user || !sheet) return null;

  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <th>Terms</th>
          <th>Contact</th>
          <th>Clashing</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {sorted((people.data ?? []).filter((p) => showRetired || !p.retired), sortKey).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>
              {p.name}
            </td>
            <td data-testid="person-grade">{p.grade}</td>
            <td data-testid="person-terms">{p.terms ?? ''}</td>
            <td data-testid="person-contact">{p.contact ?? ''}</td>
            <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                Edit
              </button>
              <PersonError personId={p.id} />
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** The people sorted by their key, ascending; equal keys (and no key) keep list order. */
function sorted(people: Person[], key: ((p: Person) => string | number) | null): Person[] {
  if (!key) return people;
  return people.map((p, i) => ({ p, i, k: key(p) })).sort((a, b) => compare(a.k, b.k) || a.i - b.i).map((e) => e.p);
}

/** The key a person sorts on: their name as names compare, their grade, or their due-total (n/a last); null: list order. */
function useSortKey(sort: SortKey): ((p: Person) => string | number) | null {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = useClaims().data ?? [];
  switch (sort) {
    case 'name':
      return (p) => nameKey(p.name);
    case 'grade':
      return (p) => p.grade;
    case 'due-total':
      return (p) => {
        const total = personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules);
        return total === NA ? Infinity : Math.round(Number(total) * 100);
      };
    default:
      return null;
  }
}
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonSelect } from './PersonSelect';

export const contributions = [
  PersonColumnHeads.fill({ order: -10, Component: () => <th>Select</th> }),
  PersonColumns.fill({ order: -10, Component: PersonSelect }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { BulkRetire } from './BulkRetire';
import { PersonRetire } from './PersonRetire';
import { ShowRetired } from './ShowRetired';

export const contributions = [
  HomeMain.fill({ order: 17, Component: ShowRetired }),
  HomeMain.fill({ order: 24.5, Component: BulkRetire }),
  PersonColumnHeads.fill({ order: 18, Component: () => <th>Retired</th> }),
  PersonColumns.fill({ order: 18, Component: PersonRetire }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { usePersonError } from '../people/personError';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// Whether the person is retired and from when, and the date and button that retire them (a blank
// date is the sheet's today). From the day the date is reached, a retired person's open and pending claims leave
// the live totals (settled and statement-bound ones still count); one dated after the date is refused. A retired
// person can be unretired on the sheet's today; each past retirement stays on the row as "<from> to <to>", and a
// claim dated after its from and before its to is refused.
export function PersonRetire({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [from, setFrom] = useState('');
  const [, setError] = usePersonError(person.id);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire?user=${encodeURIComponent(user)}`,
        { from: date },
      ),
    onSuccess: async () => {
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: () => setError('The person could not be retired.'),
  });

  const unretire = useMutation({
    mutationFn: () =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unretire?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: () => setError('Only a retired person can be unretired.'),
  });

  const submit = () => {
    setError('');
    const date = from.trim();
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => retire.mutateAsync(date));
  };

  return (
    <td>
      <span data-testid="person-retired">{person.retired ? 'yes' : 'no'}</span>{' '}
      <span data-testid="person-retired-from">{person.retiredFrom ?? ''}</span>{' '}
      <input
        data-testid="person-retire-date"
        placeholder="yyyy-mm-dd"
        value={from}
        onChange={(e) => {
          setFrom(e.target.value);
          setError('');
        }}
      />
      <button type="button" data-testid="person-retire" disabled={retire.isPending} onClick={submit}>
        Retire
      </button>{' '}
      <button
        type="button"
        data-testid="person-unretire"
        disabled={unretire.isPending}
        onClick={() => {
          setError('');
          once(() => unretire.mutateAsync());
        }}
      >
        Unretire
      </button>
      {person.pastRetirements.map((r, i) => (
        <div key={i} data-testid="person-retirement-line">
          {r.from} to {r.to}
        </div>
      ))}
    </td>
  );
}
# Edit a person's name and grade; refused (400) on the same terms as an add; someone whose name or an alias is
# already used across the sheet's tree is refused every edit until it renames them clear of it (no alias clashing).
# Refused (409) when the editor loaded a version of the person someone else has saved over since.
